// JarvisLive.js — the /jarvis route (the folder name is legacy, not the URL).
//
// A public, no-sign-in page where a visitor talks to Jarvis: the terminal AI
// coding assistant from github.com/Laxman824/JarvisAssistant, running for real
// as a serverless function. Not a mockup and not a recording — the same
// agent loop, the same tools, answering out of its own source code.
//
// It exists because CAMSCode — the enterprise version of this, and the strongest
// project on the site — can never be demonstrated. This one can, so the page
// opens with that story and then hands the visitor the thing itself.
//
// One column, read top to bottom: the answer, then the machinery that produced
// it, then the box you type in. The trace is the point, not a sidebar — the
// reasoning and the exact tool calls are what nobody else's portfolio shows.
//
// The badge on the terminal always states which transport actually served the
// answer. That honesty is a feature: a "live" badge over a canned response
// would be a lie, and the whole point of the page is that this one is real.
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import Header from "../../../components/header/Header";
import MdLite from "../../../utils/MdLite";
import { forcedTransport, health, runTurn } from "./jarvisClient";
import "./JarvisLive.css";

const SUGGESTIONS = [
  {
    label: "How does your failover work?",
    prompt:
      "How does your provider failover work? Look at _FAILOVER_CHAINS in agent/loop.py and explain in two sentences.",
  },
  {
    label: "Show me your structure",
    prompt:
      "Show me your project structure, then describe in one sentence what the agent/ folder is responsible for.",
  },
  {
    label: "How do you stay safe?",
    prompt:
      "How does your approval gate stop you from sending an email without permission? Read agent/approval.py.",
  },
  {
    label: "How many tools do you have?",
    prompt:
      "How many tools do you actually have, and how does the tool router decide which ones to offer each turn?",
  },
];

// Reduced motion is handled entirely in CSS (@media prefers-reduced-motion),
// so there is no JS check here — the only animation is the thinking ellipsis.

// ============================================
// TERMINAL — the tool trace, as it happens
// ============================================
// The terminal is the point of the page, not decoration: it shows the agent
// loop actually looping — what the model was thinking, which tool it chose,
// the exact arguments it chose, and what came back.
function Terminal({
  lines,
  status,
  busy,
  meta,
  thinking,
  showThinking,
  onToggleThinking,
}) {
  const bodyRef = useRef(null);

  // Pin to the newest line, but only inside the terminal's own scroll box —
  // never scrollIntoView, which would drag the whole page with it.
  useEffect(() => {
    const el = bodyRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [lines, busy, thinking, showThinking]);

  return (
    <div className="jv-term">
      <div className="jv-term-bar">
        <span className="jv-tdot jv-tdot-r" />
        <span className="jv-tdot jv-tdot-y" />
        <span className="jv-tdot jv-tdot-g" />
        <span className="jv-term-title">
          jarvis@vercel&nbsp;·&nbsp;~/JarvisAssistant
        </span>
        {thinking && (
          <button
            type="button"
            className="jv-term-toggle"
            onClick={onToggleThinking}
            title="Show or hide the model's reasoning"
          >
            {showThinking ? "hide reasoning" : "show reasoning"}
          </button>
        )}
        <span className={`jv-term-badge jv-badge-${status.kind}`}>
          {status.label}
        </span>
      </div>

      <div className="jv-term-body" ref={bodyRef}>
        {lines.length === 0 && !busy && (
          <div className="jv-tline jv-tline-dim">
            {"// ask something — every tool call and the model's reasoning"}
            <br />
            {"// stream in here as the agent works"}
          </div>
        )}

        {/* Reasoning first: it is what the model does *before* choosing a
            tool, so showing it above the calls matches the actual order. */}
        {thinking && showThinking && (
          <div className="jv-reason">
            <div className="jv-reason-label">reasoning</div>
            <div className="jv-reason-text">{thinking}</div>
          </div>
        )}

        {lines.map((line, i) => {
          if (line.kind === "tool") {
            return (
              <div className="jv-tool-block" key={i}>
                <div className="jv-tool">
                  <span className="jv-tool-icon">{line.icon}</span>
                  {/* The real call, arguments and all. "It read a file" is
                      trivia; "it chose to read *this* file" is the demo. */}
                  <code className="jv-tool-call">
                    {line.call || `${line.name}(…)`}
                  </code>
                  <span
                    className={`jv-tool-state jv-tool-${
                      line.state === "running"
                        ? "running"
                        : line.ok
                        ? "ok"
                        : "err"
                    }`}
                  >
                    {line.state === "running" ? "⋯" : line.ok ? "✓" : "✗"}
                  </span>
                </div>
                {line.summary && (
                  <div className="jv-tool-summary">↳ {line.summary}</div>
                )}
              </div>
            );
          }
          return (
            <div className={`jv-tline jv-tline-${line.kind}`} key={i}>
              {line.text}
            </div>
          );
        })}

        {busy && (
          <div className="jv-tline jv-tline-dim jv-thinking">
            working
            <span className="jv-dots" />
          </div>
        )}

        {meta && <div className="jv-tline jv-tline-ok">{meta}</div>}
      </div>
    </div>
  );
}

// ============================================
// MAIN
// ============================================
const JarvisLive = ({ theme, setTheme }) => {
  const [input, setInput] = useState("");
  const [turns, setTurns] = useState([]); // {role, content}
  const [streaming, setStreaming] = useState("");
  const [lines, setLines] = useState([]);
  const [busy, setBusy] = useState(false);
  const [thinking, setThinking] = useState("");
  const [showThinking, setShowThinking] = useState(true);
  const [meta, setMeta] = useState("");
  const [provider, setProvider] = useState(null);
  const [quota, setQuota] = useState(null);
  const [transport, setTransport] = useState(null); // null = unknown yet
  const [note, setNote] = useState("");

  const abortRef = useRef(null);
  const inputRef = useRef(null);
  const toolIndex = useRef({});

  const forced = useMemo(() => forcedTransport(), []);

  // Probe once so the badge is honest before the first question, rather than
  // claiming "live" and discovering otherwise mid-answer.
  useEffect(() => {
    let cancelled = false;
    if (forced === "replay") {
      setTransport("replay");
      return undefined;
    }
    health().then((info) => {
      if (cancelled) return;
      if (info && info.ok) {
        setTransport("live");
        setProvider(info.defaultProvider);
      } else {
        setTransport("down");
      }
    });
    return () => {
      cancelled = true;
    };
  }, [forced]);

  useEffect(() => () => abortRef.current?.abort(), []);

  const status = useMemo(() => {
    if (busy) return { kind: "live", label: "● running" };
    if (transport === "live") return { kind: "live", label: "● live" };
    if (transport === "replay") return { kind: "replay", label: "▸ replay" };
    if (transport === "down") return { kind: "down", label: "○ offline" };
    return { kind: "idle", label: "○ connecting" };
  }, [busy, transport]);

  const honestyLine = useMemo(() => {
    if (transport === "live") {
      return "The real Jarvis, running serverless — read-only tools, sandboxed to its own source.";
    }
    if (transport === "down") {
      return "Jarvis isn't reachable right now. The code is on GitHub in the meantime.";
    }
    if (transport === "replay") {
      return "Replaying a recorded session — not a live model call.";
    }
    return "Checking whether Jarvis is awake…";
  }, [transport]);

  const ask = useCallback(
    async (prompt) => {
      const text = (prompt || "").trim();
      if (!text || busy) return;

      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setInput("");
      setNote("");
      setMeta("");
      setLines([]);
      setStreaming("");
      setThinking("");
      toolIndex.current = {};
      setBusy(true);

      const history = turns.slice(-6);
      setTurns((prev) => [...prev, { role: "user", content: text }]);

      let answer = "";
      let reasoning = "";

      await runTurn({
        prompt: text,
        history,
        signal: controller.signal,
        onEvent: (event) => {
          switch (event.type) {
            case "status":
              setProvider(event.model || event.provider);
              setTransport(event.transport);
              if (event.quota) setQuota(event.quota);
              break;

            case "text":
              answer += event.delta;
              setStreaming(answer);
              break;

            case "thinking":
              // Reasoning tokens the terminal REPL prints in grey and throws
              // away. Recovered by wrapping the provider client, because
              // showing how the model reasons its way to a tool call is the
              // whole reason this page exists.
              reasoning += event.delta;
              setThinking(reasoning);
              break;

            case "tool_start":
              setLines((prev) => {
                toolIndex.current[event.id] = prev.length;
                return [
                  ...prev,
                  {
                    kind: "tool",
                    icon: event.icon,
                    verb: event.verb,
                    name: event.name,
                    detail: event.detail,
                    state: "running",
                  },
                ];
              });
              break;

            case "tool_args":
              setLines((prev) => {
                const at = toolIndex.current[event.id];
                if (at == null || !prev[at]) return prev;
                const next = [...prev];
                next[at] = { ...next[at], call: event.call };
                return next;
              });
              break;

            case "tool_summary":
              setLines((prev) => {
                const at = toolIndex.current[event.id];
                if (at == null || !prev[at]) return prev;
                const next = [...prev];
                next[at] = { ...next[at], summary: event.summary };
                return next;
              });
              break;

            case "tool_result":
              setLines((prev) => {
                const at = toolIndex.current[event.id];
                if (at == null || !prev[at]) return prev;
                const next = [...prev];
                next[at] = { ...next[at], state: "done", ok: event.ok };
                return next;
              });
              break;

            case "failover":
              // Worth surfacing rather than hiding: watching one provider die
              // and another pick the turn up is the clearest demonstration of
              // the failover chain the project is built around.
              setLines((prev) => [
                ...prev,
                {
                  kind: "warn",
                  text: `⚠ ${event.from} unavailable — failing over to ${event.to}`,
                },
              ]);
              break;

            case "done":
              setMeta(
                `✓ done · ${event.toolCalls} tool${
                  event.toolCalls === 1 ? "" : "s"
                } · ${(event.ms / 1000).toFixed(1)}s · ${event.inTokens} in / ${
                  event.outTokens
                } out`
              );
              break;

            case "error":
              if (event.code === "quota") {
                setNote(
                  "You've used today's free questions. The live demo is rate-limited so the free-tier keys survive the day — come back tomorrow, or read the source on GitHub."
                );
              } else if (event.code === "busy") {
                setNote(
                  "Jarvis is answering someone else. Try again in a moment."
                );
              } else {
                setNote(event.message || "Something went wrong.");
              }
              setLines((prev) => [
                ...prev,
                { kind: "err", text: `✗ ${event.message || event.code}` },
              ]);
              break;

            default:
              break;
          }
        },
      });

      setBusy(false);
      setStreaming("");
      if (answer.trim()) {
        setTurns((prev) => [...prev, { role: "assistant", content: answer }]);
      }
    },
    [busy, turns]
  );

  const onKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      ask(input);
    }
  };

  const disabled = busy || transport === "down";

  return (
    <div
      className="jv-page"
      data-theme={theme?.name}
      style={{
        "--jv-body": theme?.body,
        "--jv-text": theme?.text,
        "--jv-sub": theme?.secondaryText,
        "--jv-accent": theme?.accentColor,
      }}
    >
      <Header theme={theme} setTheme={setTheme} />

      {/* ================= WHY THIS PAGE EXISTS =================
          Without this, the page reads as one more portfolio chatbot. The
          demo only means something once you know it stands in for the
          system that can't be demonstrated. */}
      <section className="jv-intro">
        <p className="jv-eyebrow">The one I can actually show you</p>
        <h1 className="jv-title">
          I built an AI coding assistant for an enterprise.
          <br />
          <span className="jv-title-dim">
            This is the same thing, and you can use it.
          </span>
        </h1>
        <p className="jv-lede">
          At CAMS I built <strong>CAMSCode</strong> — an agentic coding
          assistant that turns specs into working applications, running entirely
          inside their network so regulated financial data never leaves it. I
          can describe it. I can't show it to you.
        </p>
        <p className="jv-lede">
          <strong>Jarvis</strong> is the same system built personally and open
          source: six LLM providers, ~100 tools, its own agent loop. It's
          running below — sandboxed to read-only access over its own source
          code. Ask it anything and watch the loop work.
        </p>
        <div className="jv-intro-links">
          <a className="jv-link" href="/projects/camscode">
            The CAMSCode case study →
          </a>
          <a
            className="jv-link"
            href="https://github.com/Laxman824/JarvisAssistant"
            target="_blank"
            rel="noreferrer"
          >
            Jarvis source on GitHub →
          </a>
        </div>

        {/* What to look for — otherwise the trace is just noise to a
            non-engineer, and the mechanism is the entire point. */}
        <ul className="jv-watch">
          <li>
            <span>reasoning</span> the model deciding what it needs
          </li>
          <li>
            <span>tool calls</span> the exact arguments it chose
          </li>
          <li>
            <span>results</span> what came back, and how it adapts
          </li>
          <li>
            <span>failover</span> a dead provider caught mid-turn
          </li>
        </ul>
      </section>

      {/* One column, read top to bottom: the answer, then the machinery that
          produced it, then the box you type in — which stays docked so the
          input is reachable however far the answer runs. */}
      <div className="jv-wrap">
        {/* ---------------- ANSWER ---------------- */}
        <section className="jv-answers">
          {turns.length === 0 && !streaming && (
            <p className="jv-empty">
              Ask something below — the answer appears here, and everything
              Jarvis did to reach it appears underneath.
            </p>
          )}
          {turns.map((turn, i) => (
            <div className={`jv-turn jv-turn-${turn.role}`} key={i}>
              {turn.role === "user" ? (
                <p className="jv-user-text">{turn.content}</p>
              ) : (
                <MdLite text={turn.content} />
              )}
            </div>
          ))}
          {streaming && (
            <div className="jv-turn jv-turn-assistant">
              <MdLite text={streaming} />
              <span className="jv-caret" />
            </div>
          )}
        </section>

        {/* ---------------- THE PROCESS ---------------- */}
        <section className="jv-stage">
          <Terminal
            lines={lines}
            status={status}
            busy={busy}
            meta={meta}
            thinking={thinking}
            showThinking={showThinking}
            onToggleThinking={() => setShowThinking((v) => !v)}
          />
          <p className="jv-honesty">{honestyLine}</p>
        </section>

        {note && <p className="jv-note">{note}</p>}

        {/* ---------------- COMPOSER (docked) ---------------- */}
        <div className="jv-dock">
          <div className={`jv-composer ${busy ? "jv-composer-busy" : ""}`}>
            <textarea
              ref={inputRef}
              className="jv-input"
              placeholder={
                transport === "down"
                  ? "Jarvis is offline right now…"
                  : "Ask Jarvis about its own code…"
              }
              value={input}
              rows={1}
              maxLength={500}
              disabled={disabled}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={onKeyDown}
            />

            <div className="jv-composer-row">
              <span className="jv-pill jv-pill-static">read-only</span>
              {/* The model is real, and it changes: a failover mid-turn
                  visibly swaps it. Worth showing for that reason alone. */}
              <span
                className="jv-model"
                title="The provider and model serving this turn"
              >
                <span className="jv-model-dot" />
                {provider || "connecting…"}
              </span>
              <button
                type="button"
                className="jv-send"
                disabled={disabled || !input.trim()}
                onClick={() => ask(input)}
              >
                {busy ? "⋯" : "↑"}
              </button>
            </div>

            {/* Session bar — the demo runs on free-tier keys, so the budget
                is real and worth being upfront about. */}
            <div className="jv-session">
              <span className={`jv-session-state jv-badge-${status.kind}`}>
                {status.label}
              </span>
              {meta && <span className="jv-session-meta">{meta}</span>}
              <span className="jv-session-quota">
                {quota
                  ? `${quota.remaining} of ${quota.limit} questions left today`
                  : "3 free questions a day"}
              </span>
            </div>
          </div>

          <div className="jv-chips">
            {SUGGESTIONS.map((s) => (
              <button
                key={s.label}
                type="button"
                className="jv-chip"
                disabled={disabled}
                onClick={() => ask(s.prompt)}
              >
                {s.label}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default JarvisLive;
