// jarvisClient.js — talks to the real Jarvis assistant running serverless.
//
// The backend is a FastAPI app in the JarvisAssistant repo, deployed as its own
// Vercel project. It streams Server-Sent Events describing a turn: the answer
// arriving as text deltas, and each tool call as it starts and finishes.
//
// EventSource cannot POST, and the prompt plus history has to go in a body, so
// this reads the stream off `fetch` manually. That also gives us AbortController
// for cancellation, which EventSource does not offer.
//
// Every transport (live now, recorded replay later) resolves to the same event
// schema, so the UI only ever learns one vocabulary:
//
//   status | text | thinking | tool_start | tool_result | failover | done | error

// The deployed Jarvis API — its own Vercel project, separate from this site.
// Override with REACT_APP_JARVIS_API to point at a local uvicorn during dev.
export const API_BASE =
  process.env.REACT_APP_JARVIS_API || "https://jarvis-live-beta.vercel.app";

const CLIENT_ID_KEY = "jarvis.demo.cid.v1";

// Stable per-browser id. The server hashes it together with the IP, so clearing
// localStorage alone does not reset the daily allowance.
export function clientId() {
  try {
    let id = localStorage.getItem(CLIENT_ID_KEY);
    if (!id) {
      id =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `c-${Date.now()}-${Math.random().toString(36).slice(2)}`;
      localStorage.setItem(CLIENT_ID_KEY, id);
    }
    return id;
  } catch {
    // Private browsing with storage disabled — the IP half still applies.
    return "no-storage";
  }
}

// `?jarvis=live|replay` pins a transport, mirroring the `?cursor=off` escape
// hatch on the showcase page.
export function forcedTransport() {
  if (typeof window === "undefined") return null;
  const value = new URLSearchParams(window.location.search).get("jarvis");
  return value === "live" || value === "replay" ? value : null;
}

export async function health(timeoutMs = 4000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${API_BASE}/api/health`, {
      signal: controller.signal,
    });
    if (!response.ok) return null;
    return await response.json();
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Run one turn. Calls onEvent for each event; resolves when the stream ends.
 *
 * Errors are delivered as `{type:"error"}` events rather than thrown, because a
 * turn can fail halfway through after useful output has already been rendered —
 * the caller wants to keep what arrived and show why it stopped.
 */
export async function runTurn({ prompt, history = [], onEvent, signal }) {
  let response;
  try {
    response = await fetch(`${API_BASE}/api/q`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt, history, clientId: clientId() }),
      signal,
    });
  } catch (err) {
    onEvent({
      type: "error",
      code: "network",
      message:
        err.name === "AbortError" ? "Cancelled." : "Could not reach Jarvis.",
    });
    return;
  }

  if (!response.ok || !response.body) {
    onEvent({
      type: "error",
      code: "network",
      message: `Jarvis returned ${response.status}.`,
    });
    return;
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  // SSE frames are separated by a blank line. A frame can straddle two chunks,
  // so the tail of the buffer is kept until its terminator arrives.
  while (true) {
    let chunk;
    try {
      chunk = await reader.read();
    } catch (err) {
      if (err.name !== "AbortError") {
        onEvent({ type: "error", code: "network", message: "Stream dropped." });
      }
      return;
    }
    if (chunk.done) break;

    buffer += decoder.decode(chunk.value, { stream: true });

    let split;
    while ((split = buffer.indexOf("\n\n")) !== -1) {
      const frame = buffer.slice(0, split);
      buffer = buffer.slice(split + 2);

      for (const line of frame.split("\n")) {
        if (!line.startsWith("data: ")) continue; // ": keepalive" comments
        try {
          onEvent(JSON.parse(line.slice(6)));
        } catch {
          // A malformed frame is not worth killing the turn over.
        }
      }
    }
  }
}
